#include <bits/stdc++.h>
using long long = long long;
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<long long> a(n);
    for(auto &x : a) cin >> x;

    vector<long long> S(n+1, 0);
    for(int i = 0; i < n; i++) S[i+1] = S[i] + a[i];

    auto solve = [&](int start_sign) -> long long {
        // start_sign = 1: odd positions (1-indexed) positive
        long long cost = 0;
        long long d = 0;
        for(int i = 1; i <= n; i++){
            int sign = (i % 2 == 1) ? start_sign : -start_sign;
            long long nd;
            if(sign == 1){
                nd = max(d, 1 - S[i]);
            } else {
                nd = min(d, -1 - S[i]);
            }
            cost += abs(nd - d);
            d = nd;
        }
        return cost;
    };

    cout << min(solve(1), solve(-1)) << endl;
}

