        // firstSign = +1 means prefix sums should be +,-,+,-,...
        // firstSign = -1 means prefix sums should be -,+,-,+,...
        int64 ans = 0;
        int64 sum = 0;

        for (int i = 0; i < N; ++i) {
            sum += a[i];
            int sign = (i % 2 == 0 ? firstSign : -firstSign);

            if (sign > 0) {
                if (sum <= 0) {
                    ans += 1 - sum;
                    sum = 1;
                }
            } else {
                if (sum >= 0) {
                    ans += sum + 1;
                    sum = -1;
                }
            }
        }
        return ans;
    };

    cout << min(calc(1), calc(-1)) << '\n';
    return 0;
}

