long long solve(long long *a, int n, int start_sign) {
    long long cost = 0;
    long long T_prev = 0;
    long long P_prev = 0;
    for (int i = 0; i < n; i++) {
        int sign = (i % 2 == 0) ? start_sign : -start_sign;
        long long P_i = P_prev + a[i];
        long long E_prev = T_prev - P_prev;
        long long ideal_T = P_i + E_prev;
        long long T_i;
        if (sign > 0) T_i = (ideal_T >= 1) ? ideal_T : 1;
        else T_i = (ideal_T <= -1) ? ideal_T : -1;
        cost += llabs(T_i - ideal_T);
        T_prev = T_i;
        P_prev = P_i;
    }
    return cost;
}

