    long long sum = 0;
    int sign = start_sign; // 1 for positive, -1 for negative

    for (int i = 0; i < n; i++) {
        sum += a[i];
        if (sign == 1) {
            if (sum <= 0) {
                long long diff = 1 - sum;
                ops += diff;
                sum = 1;
            }
        } else {
            if (sum >= 0) {
                long long diff = sum + 1;
                ops += diff;
                sum = -1;
            }
        }
        sign = -sign;
    }
    return ops;
}

