typedef long long ll;

static ll solve(ll *a, int n, int first_positive) {
    ll ans = 0;
    ll sum = 0;

    for (int i = 0; i < n; i++) {
        sum += a[i];
        int should_positive = ((i % 2) == 0) ? first_positive : !first_positive;

        if (should_positive) {
            if (sum <= 0) {
                ans += 1 - sum;
                sum = 1;
            }
        } else {
            if (sum >= 0) {
                ans += sum + 1;
                sum = -1;
            }
        }
    }
    return ans;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *a = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

    ll ans1 = solve(a, n, 1); // prefix sums: +, -, +, ...
    ll ans2 = solve(a, n, 0); // prefix sums: -, +, -, ...

    printf("%lld\n", ans1 < ans2 ? ans1 : ans2);

    free(a);
    return 0;
}

