        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();

        long[] S = new long[n];
        S[0] = a[0];
        for (int i = 1; i < n; i++) S[i] = S[i-1] + a[i];

        long ans = Long.MAX_VALUE;
        for (int start = 0; start < 2; start++) {
            // start=0: positive first, start=1: negative first
            long cost = 0;
            long d = 0;
            for (int i = 0; i < n; i++) {
                boolean wantPos = ((i + start) % 2 == 0);
                long prev = d;
                if (wantPos) {
                    long lb = 1 - S[i];
                    if (d < lb) d = lb;
                } else {
                    long ub = -1 - S[i];
                    if (d > ub) d = ub;
                }
                cost += Math.abs(d - prev);
            }
            ans = Math.min(ans, cost);
        }
        System.out.println(ans);
    }
}

